import express, { type Request, type RequestHandler, type Response } from 'express';
import { existsSync, realpathSync } from 'node:fs';
import { basename, dirname, isAbsolute, relative, resolve, sep } from 'node:path';
import { createDebug } from '../debug.js';
import { supportsVerifiedWrites } from '../document-write.js';
import type { UttoriContext } from '../custom.js';
import type { CaptureInboxConfig } from '../types/plugins/capture-inbox.js';
import type { CsrfViewModel } from '../types/plugins/csrf.js';
import type { UttoriWikiViewModel } from '../wiki.js';
import CsrfProtection from './csrf.js';
import { previousSidecars } from './storeage-provider-json/sidecar-generation.js';
import { CaptureError } from './capture-inbox/files.js';
import {
  CaptureQueue, captureId, captureUrl, captureVersion, isPdf, maxDraftBytes, maxOriginalBytes,
  prepareCapture, publishCapture, reviewCapture, type Capture,
} from './capture-inbox/queue.js';

export type { CaptureInboxConfig } from '../types/plugins/capture-inbox.js';

const debug = createDebug('Uttori.CaptureInbox');
const route = '/capture-inbox';
const escape = CsrfProtection.escapeHtml;

/**
 * Label the last durable checkpoint so maintainers can distinguish a saved page from finished indexing.
 * @param capture Private queue entry.
 * @returns State shown in the inbox and on its review screen.
 */
function status(capture: Capture): string {
  if (capture.publication?.indexed || capture.sidecars?.indexed) return 'Published';
  if (capture.publication?.stored || capture.sidecars?.stored) return 'Saved · indexing pending';
  if (capture.publication?.blocked) return 'Review needed';
  if (capture.publication || capture.sidecars?.approved) return 'Publication pending';
  if (capture.draft?.review || capture.sidecars) return 'Ready for approval';
  if (capture.draft) return 'Draft';
  if (capture.failure) return 'Preparation pending';
  return 'Queued';
}

/**
 * Send a plain HTML screen. Source and draft content are escaped before inclusion.
 * @param response Express response.
 * @param title Screen title.
 * @param body Internal markup already escaped at data boundaries.
 * @param code HTTP status.
 */
function screen(response: Response, title: string, body: string, code = 200): void {
  response.status(code).type('html').send(`<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escape(title)}</title>
<style>
  body{font:1rem/1.5 system-ui,sans-serif;color:#172129;background:#f6f8fa;margin:0}
  main{max-width:70rem;margin:auto;padding:2rem 1rem 4rem}
  section{padding:1.1rem 1.3rem;margin:1rem 0;background:white;border:1px solid #d8dfe5;border-radius:.5rem}
  label{display:block;font-weight:600;margin:.7rem 0 .25rem}
  input:not([type=hidden]),textarea{box-sizing:border-box;width:100%;padding:.55rem;font:inherit}
  button{padding:.5rem .9rem;margin-top:.8rem;font:inherit}
  a{color:#07598c} pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:26rem;overflow:auto;padding:.7rem;background:#f0f3f5}
  .comparison{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,24rem),1fr));gap:1rem}
  .notice{padding:.7rem;background:#fff0d4;border-left:.25rem solid #9f5900}
</style>
<main><h1>${escape(title)}</h1>${body}</main></html>`);
}

/**
 * Render a capture and its available state transitions.
 * @param request Express request on the inbox mount.
 * @param response Express response.
 * @param capture Current durable capture.
 * @param csrf Hidden CSRF field generated by Uttori.
 * @param [error] Rejected operation to show with the current state.
 */
function detail(request: Request, response: Response, capture: Capture, csrf: string, error?: CaptureError): void {
  const base = escape(request.baseUrl);
  const item = `${base}/${capture.id}`;
  const hidden = `${csrf}<input type="hidden" name="version" value="${captureVersion(capture)}">`;
  const failure = error?.message || capture.failure;
  const notice = failure ? `<p role="alert" class="notice">${escape(failure)}</p>` : '';
  const source = capture.url ? `<p>Source URL <code>${escape(capture.url)}</code></p>` : '';
  const original = capture.originalType ? `<p><a href="${item}/original">Download private original</a></p>` : '';
  const draft = capture.draft;
  const publication = capture.publication;
  const sidecars = capture.sidecars;
  let work = '';
  if (sidecars?.indexed && draft) {
    const wikiPath = escape(request.baseUrl.slice(0, -route.length));
    work = `<section><h2>Published page</h2><p><a href="${wikiPath}/${escape(draft.slug)}">${escape(draft.title)}</a></p>
<p>Source note <a href="${wikiPath}/${sidecars.sourceSlug}">${sidecars.sourceSlug}</a></p><p>The sidecar changes are ready for Git review.</p></section>`;
  } else if (publication?.indexed) {
    const wikiPath = escape(request.baseUrl.slice(0, -route.length));
    work = `<section><h2>Published page</h2><p><a href="${wikiPath}/${escape(publication.document.slug)}">${escape(publication.document.title)}</a></p><p>Revision <code>${escape(publication.revision)}</code></p></section>`;
  } else if (sidecars?.approved || (publication && !publication.blocked)) {
    work = `<section><h2>Resume publication</h2><p>The approved draft is saved in the inbox.</p>
<form method="post" action="${item}/publish">${hidden}<button>Resume publication</button></form></section>`;
  } else if (!draft) {
    work = `<section><h2>Prepare draft</h2><p>Convert the captured original to Markdown for review.</p>
<form method="post" action="${item}/prepare">${hidden}<button>${capture.failure ? 'Resume preparation' : 'Prepare draft'}</button></form></section>`;
  } else {
    work = `<section><h2>Edit draft</h2>
<form method="post" action="${item}/review">${hidden}
<label for="title">Title</label><input id="title" name="title" required maxlength="240" value="${escape(draft.title)}">
<label for="slug">Page slug</label><input id="slug" name="slug" required maxlength="128" pattern="[a-z0-9][a-z0-9\\-]*" value="${escape(draft.slug)}">
<label for="content">Markdown</label><textarea id="content" name="content" rows="14" required maxlength="${maxDraftBytes}">
${escape(draft.content)}</textarea>
<button>Review draft</button></form></section>`;
    if (publication?.blocked) {
      work += `<form method="post" action="${item}/publish">${hidden}<button>Resume earlier publication</button></form>`;
    } else if (sidecars) {
      const changes = sidecars.files.filter(file => file.before !== file.after).map(file => `<h3>${escape(file.name)}</h3>
<div class="comparison"><div><h4>Current</h4><pre>${escape(file.before ?? '(new file)')}</pre></div>
<div><h4>Proposed</h4><pre>${escape(file.after)}</pre></div></div>`).join('');
      work += `<section><h2>Review saved sidecar changes</h2>${changes}
<form method="post" action="${item}/publish">${hidden}<button>Approve and publish</button></form></section>`;
    } else if (draft.review) {
      const before = draft.review.before;
      const comparison = before ? `<h3>${escape(before.title)}</h3><pre>${escape(before.content)}</pre>` : '<p>This will create a new page.</p>';
      work += `<section><h2>Review saved draft</h2><p>Destination <code>${escape(draft.slug)}</code></p>
<div class="comparison"><div><h3>Current wiki page</h3>${comparison}</div><div><h3>Proposed page</h3><h4>${escape(draft.title)}</h4><pre>${escape(draft.content)}</pre></div></div>
<form method="post" action="${item}/publish">${hidden}<button>Approve and publish</button></form></section>`;
    }
  }
  screen(response, capture.label, `<p><a href="${base}/">Capture inbox</a></p><p><strong>${status(capture)}</strong></p>${notice}${source}${original}${work}`, error?.status);
}

/** @returns Whether the candidate is the root itself or one of its descendants. */
function isInside(root: string, candidate: string): boolean {
  const fromRoot = relative(root, candidate);
  return !fromRoot || (!isAbsolute(fromRoot) && fromRoot !== '..' && !fromRoot.startsWith(`..${sep}`));
}

/** Validate the paired storage configuration and keep the inbox outside the checkout and static tree. */
function validateSidecarIngest(context: UttoriContext, config: CaptureInboxConfig): void {
  const storage = context.config['uttori-plugin-storage-provider-json-file'];
  const directory = storage?.contentDirectory;
  const { events } = context.hooks;
  if (!directory || !isAbsolute(directory) || basename(directory) !== 'content' || storage.sidecarContentExtension !== 'md'
    || storage.useCache !== false || storage.useHistory !== false || (storage.extension ?? 'json') !== 'json'
    || context.config.allowCRUDRoutes !== false || context.config.publicHistory !== false
    || events['storage-get']?.callbacks.length !== 1 || events['storage-query']?.callbacks.length !== 1
    || (events['search-update']?.callbacks.length ?? 0) > 1 || context.config['uttori-plugin-search-provider-sqlite']) {
    throw new Error('Capture Inbox sidecar ingest requires read-only Markdown/JSON sidecar storage with caching and history disabled.');
  }
  // A stopped publisher can leave the last complete checkout at its recovery path.
  const active = existsSync(directory) ? directory : previousSidecars(directory);
  const content = realpathSync(active);
  const inbox = realpathSync(config.directory);
  if (content !== resolve(active) || inbox !== resolve(config.directory) || isInside(dirname(content), inbox)
    || (context.config.publicPath && isInside(realpathSync(context.config.publicPath), inbox))) {
    throw new Error('Capture Inbox sidecar ingest requires real paths and a private inbox outside the wiki checkout and public assets.');
  }
}

/** Opt-in, authenticated browser inbox for private URL and PDF captures. */
class CaptureInbox {
  /** @returns Configuration key used by Uttori. */
  static get configKey(): 'uttori-plugin-capture-inbox' {
    return 'uttori-plugin-capture-inbox';
  }

  /**
   * Register the browser routes after storage and search hooks are available.
   * @param context The active wiki and its inbox configuration.
   */
  static register(context: UttoriContext): void {
    const config = context.config[CaptureInbox.configKey];
    if (!config || typeof config.authorize !== 'function' || typeof config.directory !== 'string' || !isAbsolute(config.directory)) {
      throw new Error('Capture Inbox requires an absolute private directory and an authorize callback.');
    }
    if (context.config.publicPath && isInside(context.config.publicPath, config.directory)) {
      throw new Error('Capture Inbox directory must be outside the public assets directory.');
    }
    const origins = new Set((config.allowedOrigins ?? []).map(origin => {
      const url = new URL(origin);
      if (!['http:', 'https:'].includes(url.protocol) || url.href !== `${url.origin}/`) {
        throw new Error('Capture Inbox allowedOrigins must contain exact HTTP(S) origins.');
      }
      return url.origin;
    }));
    context.hooks.on('bind-routes', (server: import('express').Router) => {
      if (config.sidecarIngest) validateSidecarIngest(context, config);
      else if (!supportsVerifiedWrites(context)) throw new Error('Capture Inbox requires verified mutable storage with history.');
      server.use(route, CaptureInbox.router(context, config, origins));
    });
  }

  /**
   * Build the private inbox and use Uttori's session CSRF protection on each mutation.
   * @param context The active wiki.
   * @param config Validated inbox settings.
   * @param origins Exact HTTP(S) capture origins.
   * @returns Mounted browser router.
   */
  private static router(context: UttoriContext, config: CaptureInboxConfig, origins: Set<string>): import('express').Router {
    const router = express.Router();
    const queue = new CaptureQueue(config.directory);
    const busy = new Set<string>();
    const csrfConfig = { ...CsrfProtection.defaultConfig(), sessionKey: 'uttoriCaptureInboxCsrf', checkFetchMetadata: true };
    const csrfContext = { ...context, config: { ...context.config, [CsrfProtection.configKey]: csrfConfig } };
    const csrfInput = (request: Request) => CsrfProtection.injectToken<UttoriWikiViewModel & { csrf?: CsrfViewModel }>(
      context.buildViewModelBase(request, { title: 'Capture inbox' }),
      csrfContext,
    ).csrf?.input ?? '';

    router.use(...(config.middleware ?? []), async (request, response, next) => {
      response.set({
        'Cache-Control': 'no-store',
        'Content-Security-Policy': 'default-src \'none\'; style-src \'unsafe-inline\'; form-action \'self\'; frame-ancestors \'none\'; base-uri \'none\'',
        'X-Content-Type-Options': 'nosniff',
        'Referrer-Policy': 'no-referrer',
      });
      if (await config.authorize(request) !== true) {
        response.status(403).send('Maintainer access required.');
        return;
      }
      if (!request.session) {
        response.status(503).send('Capture Inbox requires an Express session.');
        return;
      }
      next();
    });
    router.use(express.urlencoded({ extended: false, limit: '1mb' }));
    const csrf: RequestHandler = (request, response, next) => {
      if (CsrfProtection.validateToken(request, csrfContext)) {
        response.status(403).send('Reload the inbox and submit the form again.');
        return;
      }
      next();
    };

    router.get('/', async (request, response) => {
      const entries = await queue.list();
      const token = csrfInput(request);
      const base = escape(request.baseUrl);
      const list = entries.map(capture => `<li><a href="${base}/${capture.id}">${escape(capture.label)}</a> · ${status(capture)}</li>`).join('');
      const urlForm = origins.size ? `<form method="post" action="${base}/url">${token}
<label for="url">Page or PDF URL</label><input id="url" name="url" type="url" required maxlength="2048">
<button>Queue URL</button></form>` : '';
      screen(response, 'Capture inbox', `<section><h2>Add a capture</h2>${urlForm}
<form method="post" action="${base}/pdf" enctype="multipart/form-data">${token}
<label for="pdf">PDF file</label><input id="pdf" name="pdf" type="file" accept="application/pdf,.pdf" required>
<button>Queue PDF</button></form></section>
<section><h2>Review queue</h2>${list ? `<ul>${list}</ul>` : '<p>The inbox is empty.</p>'}</section>`);
    });

    router.post('/url', csrf, async (request, response) => {
      const url = captureUrl((request.body as Record<string, unknown>)?.url, origins);
      const label = `${url.hostname}${url.pathname}`.slice(0, 240);
      const capture = await queue.create({ label, url: url.href });
      response.redirect(303, `${request.baseUrl}/${capture.id}`);
    });

    router.post('/pdf', async (request, response, next) => {
      // Authorize first and bound multipart allocation before parsing the CSRF field.
      const { default: multer } = await import('multer');
      const upload = multer({ storage: multer.memoryStorage(), limits: { fileSize: maxOriginalBytes, files: 1, fields: 1, fieldSize: 1024 } }).single('pdf');
      upload(request, response, (error?: unknown) => {
        if (error) next(new CaptureError(400, 'Upload one PDF up to 10 MiB.'));
        else next();
      });
    }, csrf, async (request, response) => {
      const pdf = request.file;
      if (!pdf?.buffer || !isPdf(pdf.buffer)) throw new CaptureError(400, 'Choose a valid PDF file.');
      const capture = await queue.create({ label: pdf.originalname.slice(0, 240) || 'PDF capture' }, pdf.buffer);
      response.redirect(303, `${request.baseUrl}/${capture.id}`);
    });

    router.get('/:id', async (request, response) => {
      const capture = await queue.read(request.params.id);
      if (!capture) throw new CaptureError(404, 'Capture not found.');
      detail(request, response, capture, csrfInput(request));
    });
    router.get('/:id/original', async (request, response) => {
      const capture = await queue.read(request.params.id);
      if (!capture?.originalType) throw new CaptureError(404, 'Original is unavailable.');
      response.download(queue.original(capture), `original.${capture.originalType}`);
    });

    router.post('/:id/:action', csrf, async (request, response) => {
      const { id, action } = request.params;
      if (typeof id !== 'string' || typeof action !== 'string' || !captureId.test(id) || !['prepare', 'review', 'publish'].includes(action)) {
        throw new CaptureError(404, 'Capture action not found.');
      }
      if (busy.has(id)) throw new CaptureError(409, 'This capture is busy. Reload its review page.');
      busy.add(id);
      try {
        const capture = await queue.read(id);
        if (!capture) throw new CaptureError(404, 'Capture not found.');
        const input = (request.body ?? {}) as Record<string, unknown>;
        const completed = capture.publication?.indexed || capture.sidecars?.indexed;
        if (input.version !== captureVersion(capture) && !(action === 'publish' && completed)) {
          detail(request, response, capture, csrfInput(request), new CaptureError(409, 'This capture changed. Review the current draft.'));
          return;
        }
        try {
          if (action === 'prepare') await prepareCapture(queue, capture, origins, config.sidecarIngest);
          if (action === 'review') await reviewCapture(context, queue, capture, input);
          if (action === 'publish') await publishCapture(context, queue, capture);
        } catch (error) {
          if (!(error instanceof CaptureError)) throw error;
          detail(request, response, await queue.read(id) ?? capture, csrfInput(request), error);
          return;
        }
        response.redirect(303, `${request.baseUrl}/${id}`);
      } finally {
        busy.delete(id);
      }
    });

    router.use((error: unknown, request: Request, response: Response, next: express.NextFunction) => {
      if (response.headersSent) {
        next(error);
        return;
      }
      if (error instanceof CaptureError) {
        screen(response, 'Capture inbox', `<p role="alert">${escape(error.message)}</p><p><a href="${escape(request.baseUrl)}/">Return to inbox</a></p>`, error.status);
        return;
      }
      debug('Capture request failed:', error);
      screen(response, 'Capture inbox', '<p role="alert">The request could not finish. Reload the inbox to see the last saved checkpoint.</p>', 500);
    });
    return router;
  }
}

export default CaptureInbox;
